      isTouchRef.current = false;
      return;
    }
    if (!isOpenRef.current) return;

    updateHover(e);

    const finalSelected = hoveredRef.current;

    isOpenRef.current = false;
    setIsOpen(false);
    hoveredRef.current = null;
    setHovered(null);

